WITH category_node AS (
    SELECT id FROM sys_category WHERE app_code = 'youanshang' AND type = 'knowledge_point' AND code = 'kp_eng_e_up_down'
)
INSERT INTO sys_content (app_code, title, slug, content_json, content_html, summary, category_id, tags, is_pinned, is_public, is_published, publish_time, view_count, sort_order, extra, created_by, created_time)
SELECT 'gongkao', '效率提升降低', 'kp-eng-e-up-down', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "效率提升与降低"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心定义：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "工程中途因技术、熟练度等原因导致效率发生比例变化。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、题型定义与识别"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "经典句式：“工作 5 天后，采用了新技术，效率提高了 20% / 变成了原来的 1.5 倍”。"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "二、核心公式"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "原效率与新效率之间存在明确的倍数关系，直接利用比例给效率赋特值。"}]}, {"type": "katexBlock", "attrs": {"content": "P_{新} = P_{旧} \\times (1 + 提升率)"}}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "三、标准步骤"}]}, {"type": "text-diagram", "attrs": {"type": "mermaid", "content": "flowchart TD\nA[看到效率提高x%] --> B[将提高后的比例化为最简分数 (如提高20% -> 6/5)]\nB --> C[直接令 P旧 = 分母(5), P新 = 分子(6)]\nC --> D[结合原定总时间算出总量 W = P旧 × T总]\nD --> E[分段计算: 突变前完成的量 + 突变后完成的量 = W]\nE --> F[解出突变后花费的实际时间]"}}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "四、例题完整推导"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "【例题】", "marks": [{"type": "bold"}]}, {"type": "text", "text": " 某工程原计划 20 天完成。干了 5 天后，效率提升了 25%，问提前了几天完工？"}]}, {"type": "orderedList", "attrs": {"start": 1}, "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "赋效率：提升 25% 即变成原来的 125%，化为 5/4。令 P旧 = 4，P新 = 5。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "求总量：原计划 20 天，每天干 4。总量 W = 4 × 20 = 80。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "算前半段：干了 5 天，完成量 = 4 × 5 = 20。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "算后半段：剩下 80 - 20 = 60。新效率是 5，耗时 = 60 ÷ 5 = 12 天。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "比对时间：原计划还要 15 天，现在只需 12 天。提前了 15 - 12 = 3 天。"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "五、易错点纠偏"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fef2f2", "borderColor": "#ef4444", "icon": "⚠️"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "死扣百分数硬算：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "如果令 P旧 = 1，P新 = 1.25，后续计算会引入小数除法（如 15 ÷ 1.25）。考场上任何小数运算都是埋雷。必须在第一步就把百分数化为整数的比例赋值！"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "六、刷题建议"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "条件反射训练：看到“提高20%”写 5和6；看到“降低25%”写 4和3；看到“提高三分之一”写 3和4。"}]}]}$$ AS jsonb), NULL, '效率提升降低的核心考点与实战推导。', category_node.id, CAST('["数量关系", "工程问题", "效率提升降低"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_eng_e_up_down", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
FROM category_node ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content_json = EXCLUDED.content_json, summary = EXCLUDED.summary, category_id = EXCLUDED.category_id, tags = EXCLUDED.tags, updated_time = NOW();
